BEGIN;
INSERT INTO auth.users(id) VALUES('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
SET LOCAL ROLE service_role;
DO $$ DECLARE a jsonb;b jsonb;rid uuid;r jsonb;pid uuid := 'cccccccc-cccc-4ccc-8ccc-cccccccccccc';BEGIN
 PERFORM public.fj_set_privacy('11111111-1111-4111-8111-111111111111',true,true,'2026-10-v2');
 IF EXISTS(SELECT 1 FROM public.user_access WHERE user_id='11111111-1111-4111-8111-111111111111' AND trial_started_at IS NOT NULL) THEN RAISE EXCEPTION 'consent started trial';END IF;
 a:=public.fj_record_calculation('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'calculate_numerology','test-v1',current_date,'work','unknown',true);
 b:=public.fj_record_calculation('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'calculate_numerology','test-v1',current_date,'work','unknown',true);
 IF (a->>'ok')::boolean IS DISTINCT FROM true OR (b->>'replayed')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'retry failed';END IF;
 IF (SELECT sum(used_count) FROM public.usage_counters WHERE user_id='11111111-1111-4111-8111-111111111111')<>1 THEN RAISE EXCEPTION 'double quota';END IF;
 b:=public.fj_record_calculation('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('b',64),'calculate_numerology','test-v1',current_date,'work','unknown',true);
 IF b->>'reason'<>'IDEMPOTENCY_CONFLICT' THEN RAISE EXCEPTION 'different input accepted';END IF;
 rid:=(a->>'readingId')::uuid;
 PERFORM public.fj_submit_feedback('11111111-1111-4111-8111-111111111111',rid,5::smallint,'unclear');
 BEGIN INSERT INTO public.reading_feedback(user_id,reading_id,usefulness,match_assessment)
 VALUES('22222222-2222-4222-8222-222222222222',rid,5,'matched');RAISE EXCEPTION 'cross user feedback allowed';EXCEPTION WHEN foreign_key_violation THEN NULL;END;
 PERFORM public.fj_set_privacy('11111111-1111-4111-8111-111111111111',false,false,'2026-10-v2');
 IF EXISTS(SELECT 1 FROM public.funnel_events WHERE user_id='11111111-1111-4111-8111-111111111111') OR EXISTS(SELECT 1 FROM public.reading_feedback WHERE user_id='11111111-1111-4111-8111-111111111111') OR EXISTS(SELECT 1 FROM public.user_readings WHERE user_id='11111111-1111-4111-8111-111111111111' AND topic IS NOT NULL) THEN RAISE EXCEPTION 'withdrawal incomplete';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_readings WHERE id=rid) THEN RAISE EXCEPTION 'operational idempotency lost on withdrawal';END IF;
 UPDATE public.user_access SET suspended_at=now() WHERE user_id='11111111-1111-4111-8111-111111111111';
 b:=public.fj_record_calculation('11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64),'calculate_numerology','test-v1',current_date);
 IF b->>'reason'<>'ACCOUNT_SUSPENDED' THEN RAISE EXCEPTION 'suspended retry allowed';END IF;
 INSERT INTO public.fortune_posts(id,account_key,body,body_sha256) VALUES(pid,'123','test-only post',repeat('c',64));
 PERFORM public.fj_approve_post(pid,repeat('c',64));
 BEGIN PERFORM public.fj_claim_publish(pid,repeat('d',64));RAISE EXCEPTION 'wrong content hash allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'POST_NOT_APPROVED_OR_NOT_DUE' THEN RAISE;END IF;END;
 r:=public.fj_claim_publish(pid,repeat('c',64));IF (r->>'acquired')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'not claimed';END IF;
 b:=public.fj_claim_publish(pid,repeat('c',64));IF (b->>'acquired')::boolean IS DISTINCT FROM false THEN RAISE EXCEPTION 'double publish claim';END IF;
 PERFORM public.fj_finish_publish(pid,(r->>'runId')::uuid,NULL,'12345','THREADS_NETWORK_ERROR');
 b:=public.fj_claim_publish(pid,repeat('c',64));IF b->>'status'<>'publish_unknown' THEN RAISE EXCEPTION 'unknown publication retried';END IF;
END; $$;
RESET ROLE;
ROLLBACK;
